import * as engine from './engine.js';
import {missionIdentity,displayAgent,accountLinks,localPreview} from './account.js';
import {instrument} from './instruments.js';
import {Atmosphere} from './audio.js';

const slugs=['sand-map','third-exposure','seventh-rinse','the-dry-tide','the-rain-register'];
const $=selector=>document.querySelector(selector);
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paragraphs=items=>(items||[]).map(p=>`<p>${esc(p)}</p>`).join('');
const byId=(items,id)=>items.find(item=>item.id===id);
const button=(label,action,attrs='',classes='')=>`<button type="button" class="btn ${classes}" data-action="${action}" ${attrs}>${label}</button>`;
const sceneLink=slug=>localPreview?`?game=${encodeURIComponent(slug)}`:`https://bureauobscura.com/${slug}`;
const topTarget=localPreview?'':'target="_top"';
let identity=null,games=[],game=null,state=null,book={},storageKey='',identityRevision=0,ready=false;
let markers=true,selectedClues=[],hints={},modal=null,modalScroll=0,returnFocus=null,returnFocusSelector='',noticeTimer;
const audio=new Atmosphere();
const emptyRecord=()=>({state:null,checkpoints:[],endings:[]});
const record=()=>book[game.slug]||(book[game.slug]=emptyRecord());
function save(){if(!ready||!identity?.allowed||!game)return;record().state=state;try{localStorage.setItem(storageKey,JSON.stringify(book));}catch{notify('This browser cannot save progress. Keep this tab open to finish the assignment.');}}
function loadBook(){try{const value=JSON.parse(localStorage.getItem(storageKey)||'{}');book=value&&typeof value==='object'&&!Array.isArray(value)?value:{};}catch{book={};}for(const g of games){const raw=book[g.slug];if(!raw||typeof raw!=='object'){book[g.slug]=emptyRecord();continue;}book[g.slug]={state:engine.restoreState(g,raw.state),checkpoints:(Array.isArray(raw.checkpoints)?raw.checkpoints:[]).map(c=>({label:String(c?.label||'Decision').slice(0,100),state:engine.restoreState(g,c?.state)})).filter(c=>c.state).slice(-8),endings:[...new Set((Array.isArray(raw.endings)?raw.endings:[]).filter(id=>g.endings.some(e=>e.id===id)))]};}}
function notify(message){if($('#dialog').open){$('#dialog-notice').textContent=message;$('#dialog-notice').hidden=false;return;}$('#notice').textContent=message;$('#notice').classList.add('visible');clearTimeout(noticeTimer);noticeTimer=setTimeout(()=>$('#notice').classList.remove('visible'),6000);}
function checkpoint(label){record().checkpoints.push({label,state:structuredClone(state)});record().checkpoints=record().checkpoints.slice(-8);}
function commit(next,kind){if(next===state)return false;state=next;save();if(kind)audio.cue(kind);render();return true;}
function header(){return `<header class="masthead"><a class="masthead-brand" href="${sceneLink('deployments')}" ${topTarget} aria-label="Bureau Obscura deployments"><img class="brand-lockup" src="assets/brand/bo-lockup-stacked-no-division-paper.svg" alt="Bureau Obscura"></a><div class="account"><span>${esc(displayAgent(identity))}</span><a href="${esc(accountLinks.fieldRecovery)}" ${topTarget}>Field Recovery ↗</a></div><nav class="top-controls" aria-label="Game controls">${game?button('Games','library','','text-btn')+button('Brief','brief','','text-btn'):''}${button(audio.enabled?'Sound on':'Sound off','sound',`aria-pressed="${audio.enabled}"`,'text-btn')}</nav></header>`;}
function progress(g){const saved=book[g.slug];if(!saved?.state?.started)return 'Begin assignment';return saved.state.ending?`${saved.endings.length} of ${g.endings.length} endings found`:`Continue · ${saved.state.evidence.length}/${g.evidence.length} clues`;}
function library(){let ninthProgress='Begin assignment';try{const old=JSON.parse(localStorage.getItem(`bureau-ninth-pane-v3:${identity.storageKey}`)||'{}');if(old.state?.started)ninthProgress='Continue assignment';}catch{}
  return `${header()}<main id="main" class="library"><div class="library-intro"><p class="eyebrow"><i></i> Field assignments</p><h1>Deployments</h1><p>Bureau Obscura recovers the scent of places across time. In these games, you are the agent sent to investigate. Read your brief, follow the physical evidence, and choose what you bring back.</p><p class="muted">Choose a game. Your progress is saved to this browser for your Bureau account.</p></div><div class="game-grid"><a class="game-card" href="${localPreview?'http://127.0.0.1:4177/':'https://bureauobscura.com/the-ninth-pane'}" ${topTarget}><div class="card-photo"><img src="assets/scenes/ninth-pane.jpg" alt="Rain outside an empty glasshouse" loading="lazy"><span>01</span></div><div class="card-copy"><p class="label">Glasshouse · 1931</p><h2>The Ninth Pane</h2><p>Investigate an extra room inside a closed glasshouse, recover its orange scent, and choose what to preserve.</p><div class="card-bottom"><span>20–30 minutes</span><strong>${ninthProgress} ↗</strong></div></div></a>${games.map(g=>`<a class="game-card" href="${sceneLink(g.slug)}" ${topTarget}><div class="card-photo"><img src="${esc(g.scenes[0].image)}" alt="${esc(g.scenes[0].title)}" loading="lazy"><span>${esc(g.number)}</span></div><div class="card-copy"><p class="label">${esc(g.coordinate)}</p><h2>${esc(g.title)}</h2><p>${esc(g.summary)}</p><div class="card-bottom"><span>${esc(g.duration)}</span><strong>${esc(progress(g))} ↗</strong></div></div></a>`).join('')}</div><footer class="library-footer"><a href="${esc(accountLinks.home)}" ${topTarget}>Return to Bureau Obscura ↗</a><span>Assignments can be replayed from saved decisions.</span></footer></main>`;}
function cover(){return `${header()}<main id="main" class="cover"><div class="cover-art"><img src="${esc(game.scenes[0].image)}" alt="${esc(game.scenes[0].title)}"><span class="cover-number">${esc(game.number)}</span></div><div class="cover-copy"><p class="eyebrow"><i></i> Bureau assignment ${esc(game.number)}</p><h1>${esc(game.title)}</h1><p class="coordinate">${esc(game.coordinate)}</p>${paragraphs(game.intro)}<div class="cover-actions">${button(state.started?'Continue assignment':'Read the brief','start','','primary')}${state.started?button('Start another run','restart','','text-btn'):''}</div><p class="small muted">${esc(game.duration)} · ${game.endings.length} possible endings · Progress saves as you play</p></div></main>`;}
function sensory(data){return `<dl class="sensory">${Object.entries(data).map(([key,value])=>`<div><dt>${esc(key)}</dt><dd>${esc(value)}</dd></div>`).join('')}</dl>`;}
function sceneView(){const scene=byId(game.scenes,state.scene),index=game.scenes.indexOf(scene);audio.setScene(game.motif,scene.weather);
  return `${header()}<main id="main" class="game-layout"><section class="scene-stage ${markers?'':'markers-off'}" aria-labelledby="scene-title"><div class="scene-square"><img class="scene-photo" src="${esc(scene.image)}" alt="${esc(scene.title)}"><div class="scene-shade"></div><div class="scene-header"><p class="label"><span>${String(index+1).padStart(2,'0')}</span> ${esc(scene.subtitle)}</p><h1 id="scene-title">${esc(scene.title)}</h1></div><div class="hotspots">${scene.hotspots.map((h,i)=>`<button type="button" class="hotspot ${state.evidence.includes(h.evidence)?'found':''}" style="left:${h.x}%;top:${h.y}%" data-action="evidence" data-id="${esc(h.evidence)}"><span class="hotspot-dot">${state.evidence.includes(h.evidence)?'✓':String(i+1).padStart(2,'0')}</span><span class="hotspot-name">${esc(h.label)}</span></button>`).join('')}</div><div class="scene-bottom"><span class="label">${esc(scene.weatherLabel||game.coordinate)}</span>${button(markers?'Hide labels':'Show labels','markers',`aria-pressed="${markers}"`,'text-btn')}</div></div></section><aside class="note-panel"><div class="note-heading"><p class="label">${esc(game.title)}</p><span class="signal">●</span></div>${paragraphs(scene.description)}${game.choices.filter(c=>c.location===scene.id&&state.choices[c.id]).map(c=>`<p class="change-note">${esc(byId(c.options,state.choices[c.id]).sceneNote)}</p>`).join('')}${sensory(scene.sensory)}<div class="scene-actions">${!state.baseline&&game.baseline.location===scene.id?button(esc(game.baseline.title),'baseline','','primary'):''}${!state.baseline&&game.baseline.location!==scene.id?`<p class="instruction">First take your baseline at ${esc(byId(game.scenes,game.baseline.location).title)}. You can inspect the other rooms before intervening.</p>`:''}${scene.hotspots.map(h=>button(`${state.evidence.includes(h.evidence)?'✓ ':''}${esc(h.label)}`,'evidence',`data-id="${esc(h.evidence)}"`,'clue-action')).join('')}${game.choices.filter(c=>c.location===scene.id).map(c=>button(`${state.choices[c.id]?'✓ ':''}${esc(c.title)}`,'choice',`data-id="${esc(c.id)}"`)).join('')}${game.puzzle.location===scene.id?button(`${state.puzzle?'✓ ':''}${esc(game.puzzle.title)}`,'puzzle','','instrument-action'):''}</div><div class="record-tools">${button(`Notebook <span>${state.evidence.length}/${game.evidence.length}</span>`,'notebook')}${button('Choose a recovery','recoveries')}${button('Revisit a decision','checkpoints','','text-btn')}</div><p class="autosave">${state.events.length?'Progress saved':'Assignment open'}</p></aside></main><nav class="scene-nav" aria-label="Locations">${game.scenes.map((s,i)=>`<button type="button" data-action="travel" data-id="${esc(s.id)}" ${state.scene===s.id?'aria-current="location"':''}><span>${String(i+1).padStart(2,'0')}</span><strong>${esc(s.title)}</strong><i>${s.hotspots.every(h=>state.evidence.includes(h.evidence))?'✓':state.visited.includes(s.id)?'·':''}</i></button>`).join('')}</nav>`;}
function endingView(){const ending=byId(game.endings,state.ending);return `${header()}<main id="main" class="ending-page"><div class="ending-art"><img src="${esc(byId(game.scenes,state.scene).image)}" alt="${esc(byId(game.scenes,state.scene).title)}"></div><article class="ending-copy"><p class="eyebrow"><i></i> Recovery filed · ${esc(ending.subtitle)}</p><h1>${esc(ending.title)}</h1>${paragraphs(ending.body)}${paragraphs(engine.epilogue(game,state))}<h2>Returned to the Bureau</h2><ul>${ending.recovered.map(item=>`<li>${esc(item)}</li>`).join('')}</ul><p class="site-status">${esc(ending.siteStatus)}</p>${sensory(ending.sensory)}<div class="ending-actions">${button('Revisit a decision','checkpoints','','primary')}${button('Download field record','download')}${button('Other recoveries','recoveries')}${button('Choose another game','library','','text-btn')}</div><p class="small muted">${record().endings.length} of ${game.endings.length} endings found.</p></article></main>`;}
function render(){if(!ready)return;$('#app').innerHTML=!game?library():!state.started?cover():state.ending?endingView():sceneView();document.title=game?`${game.title} | Bureau Obscura`:'Deployments | Bureau Obscura';}
function focusSelector(node){if(!node?.dataset?.action)return '';return ['action','id','value'].filter(key=>node.dataset[key]!==undefined).map(key=>`[data-${key}="${CSS.escape(node.dataset[key])}"]`).join('');}
function openModal(kind,id,keep=false){if(!ready)return;const activeSelector=keep?focusSelector(document.activeElement):'';if(!keep){if(!$('#dialog').open){returnFocus=document.activeElement;returnFocusSelector=focusSelector(returnFocus);}modalScroll=0;$('#dialog-notice').hidden=true;}else modalScroll=$('#dialog').scrollTop;modal={kind,id};renderModal();if(!$('#dialog').open)$('#dialog').showModal();else if(!keep)$('#dialog-title')?.focus({preventScroll:true});$('#dialog').scrollTop=modalScroll;if(activeSelector){const target=$('#dialog-body').querySelector(activeSelector)||$('#dialog-title');target?.focus({preventScroll:true});}else if(keep)$('#dialog-title')?.focus({preventScroll:true});}
function modalHeader(title,label=''){return `${label?`<p class="label signal">${esc(label)}</p>`:''}<h2 id="dialog-title" tabindex="-1">${esc(title)}</h2>`;}
function hintBlock(key,items){const count=hints[key]||0;return `<div class="hint">${paragraphs(items.slice(0,count))}${count<items.length?button(count?'Another hint':'Show a hint','hint',`data-id="${esc(key)}"`,'text-btn'):''}</div>`;}
function renderModal(){if(!modal||!game)return;let html='';const id=modal.id;
  if(modal.kind==='brief')html=modalHeader(game.title,'Assignment brief')+`<p class="coordinate">${esc(game.coordinate)}</p>`+paragraphs(game.brief)+`<div class="instruction"><strong>Your first step</strong><p>Go to ${esc(byId(game.scenes,game.baseline.location).title)} and ${esc(game.baseline.title.toLowerCase())}.</p></div>`+button(state.started?'Return to the assignment':'Deploy','deploy','','primary');
  if(modal.kind==='baseline')html=modalHeader(game.baseline.title,'Baseline survey')+paragraphs(game.baseline.body)+button('Take and seal the baseline','survey','','primary');
  if(modal.kind==='evidence'){const e=byId(game.evidence,id),found=state.evidence.includes(id),inRoom=state.scene===e.location,blocked=e.intervention&&!state.baseline;
    html=modalHeader(e.title,e.kind)+`<div class="evidence-layout ${modal.enlarged?'is-enlarged':''}"><figure class="evidence-photo"><button type="button" class="evidence-image-button" data-action="enlarge-evidence" aria-label="${modal.enlarged?'Return to observation':'Enlarge photograph'}" aria-expanded="${!!modal.enlarged}"><img src="${esc(e.visual?.image)}" alt="${esc(e.visual?.alt)}" width="1254" height="1254" decoding="async"><span class="photo-control">${modal.enlarged?'− Return to observation':'+ Enlarge photograph'}</span></button><figcaption>${esc(e.visual?.caption)}</figcaption></figure><div class="evidence-observation" ${modal.enlarged?'hidden':''}><p class="label muted">${esc(byId(game.scenes,e.location).title)} · Observation ${String(game.evidence.indexOf(e)+1).padStart(2,'0')}</p>`;
    if(found)html+=paragraphs(e.body)+`<blockquote>${esc(e.excerpt)}</blockquote><p class="signal small">Recorded in your notebook.</p>`;
    else {
      html+=paragraphs([e.examination?.lead]);
      if(blocked)html+=`<p class="instruction">Take your baseline at ${esc(byId(game.scenes,game.baseline.location).title)} before this test.</p>`;
      else if(inRoom)html+=button(esc(e.examination?.action),'inspect',`data-id="${esc(id)}"`,'primary');
      else html+=`<p>Return to ${esc(byId(game.scenes,e.location).title)} to inspect this clue.</p>`;
    }
    html+='</div></div>';
  }
  if(modal.kind==='notebook')html=modalHeader('Field notebook',`${state.evidence.length} of ${game.evidence.length} clues recorded`)+`<p>Select two recorded clues to establish a finding. You can open each observation again below.</p><div class="notebook-layout"><div><div class="clue-grid">${game.evidence.map(e=>`<div class="notebook-clue ${state.evidence.includes(e.id)?'recorded':''}"><button type="button" data-action="select-clue" data-id="${esc(e.id)}" aria-pressed="${selectedClues.includes(e.id)}" ${state.evidence.includes(e.id)?'':'disabled'}><span class="label">${esc(byId(game.scenes,e.location).title)}</span><strong>${state.evidence.includes(e.id)?esc(e.title):'Unrecorded observation'}</strong></button>${state.evidence.includes(e.id)?button('Read','evidence',`data-id="${esc(e.id)}"`,'text-btn'):''}</div>`).join('')}</div>${button(`Compare selected clues (${selectedClues.length}/2)`,'connect',selectedClues.length===2?'':'disabled','primary')}</div><div class="deductions">${game.deductions.map(d=>`<article><p class="label ${state.deductions.includes(d.id)?'signal':''}">${state.deductions.includes(d.id)?'✓ Finding recorded':'Open question'}</p><h3>${esc(d.title)}</h3><p>${esc(state.deductions.includes(d.id)?d.success:d.question)}</p>${state.deductions.includes(d.id)?'':hintBlock(d.id,d.hints)}</article>`).join('')}</div></div>`;
  if(modal.kind==='choice'){const c=byId(game.choices,id);html=modalHeader(c.title,'Preparation')+paragraphs(c.intro)+`<div class="decision-options">${c.options.map(o=>{const check=engine.choiceAvailability(game,state,c.id,o.id),chosen=state.choices[c.id]===o.id;return `<article class="decision ${chosen?'chosen':''}"><h3>${esc(o.label)}</h3><p>${esc(o.description)}</p><p class="cost">${esc(o.cost)}</p>${chosen?paragraphs(o.result)+`<p class="signal">✓ This preparation is recorded.</p>`:button('Choose this preparation','choose',`data-id="${esc(c.id)}" data-value="${esc(o.id)}" ${check.available?'':'disabled'}`)}${!chosen&&!check.available?`<p class="small muted">${esc(check.reason)}</p>`:''}</article>`;}).join('')}</div>`;}
  if(modal.kind==='puzzle'){const missing=engine.requirementLabels(game,state,game.puzzle.requires);const available=state.baseline&&!missing.length&&state.scene===game.puzzle.location;html=modalHeader(game.puzzle.title,'Field instrument')+paragraphs(game.puzzle.intro);if(!available)html+=`<p class="instruction">${!state.baseline?'Take your baseline first. ':''}${state.scene!==game.puzzle.location?`Return to ${esc(byId(game.scenes,game.puzzle.location).title)}. `:''}${missing.length?`First record: ${esc(missing.join('; '))}.`:''}</p>`;else html+=instrument(game,state)+(state.puzzle?`<div class="instruction signal">${paragraphs(game.puzzle.success)}</div>`:button('Test the arrangement','test','','primary'))+hintBlock('puzzle',game.puzzle.hints);}
  if(modal.kind==='recoveries')html=modalHeader('Choose the recovery','Return with the evidence')+`<p>Each method preserves something different. Check the consequence before you commit. Your current position will be saved so you can return to this decision.</p><div class="recovery-list">${game.endings.map(e=>{const check=engine.endingAvailability(game,state,e.id);return `<article><p class="label ${record().endings.includes(e.id)?'signal':''}">${record().endings.includes(e.id)?'✓ Ending found':esc(e.subtitle)}</p><h3>${esc(e.title)}</h3><p>${esc(e.action)}</p><p class="cost">${esc(e.consequence)}</p>${button('Review this recovery','confirm-ending',`data-id="${esc(e.id)}" ${check.available?'':'disabled'}`)}${!check.available?`<p class="small muted">${esc(check.reason)}</p>`:''}</article>`;}).join('')}</div>`;
  if(modal.kind==='confirm-ending'){const e=byId(game.endings,id);html=modalHeader(e.title,'Final recovery')+`<p>${esc(e.action)}</p><p class="cost">${esc(e.consequence)}</p>`+button('Complete the recovery and return','finish',`data-id="${esc(id)}"`,'primary');}
  if(modal.kind==='checkpoints')html=modalHeader('Revisit a decision','Saved positions')+`<p>Revisiting restores your observations and preparations to that point. Endings you have found stay in your record.</p><div class="checkpoint-list">${record().checkpoints.map((c,i)=>button(esc(c.label),'rewind',`data-id="${i}"`)).reverse().join('')||'<p>No decisions have been committed yet.</p>'}</div>`+button('Start a fresh assignment','restart','','text-btn');
  if(modal.kind==='restart')html=modalHeader('Start another run')+`<p>This begins the assignment again. Found endings remain recorded. Your current position will be kept under saved decisions.</p>`+button('Begin a fresh assignment','restart-confirm','','primary');
  $('#dialog-body').innerHTML=html;
}
function closeModal(){modal=null;$('#dialog-notice').hidden=true;$('#dialog').close();let target=returnFocus?.isConnected?returnFocus:returnFocusSelector?$('#app').querySelector(returnFocusSelector):null;if(!target){target=$('#main h1');target?.setAttribute('tabindex','-1');}target?.focus({preventScroll:true});}
function download(){const ending=byId(game.endings,state.ending);const content=[game.title,game.coordinate,displayAgent(identity),'',...(ending?ending.body:[]),'',...state.events.map(e=>engine.eventText(game,e)),'',...(ending?engine.epilogue(game,state):[])].join('\n\n');const url=URL.createObjectURL(new Blob([content],{type:'text/plain;charset=utf-8'}));const link=document.createElement('a');link.href=url;link.download=`bureau-${game.slug}-field-record.txt`;link.click();setTimeout(()=>URL.revokeObjectURL(url),5000);}
document.addEventListener('click',async event=>{const node=event.target.closest('[data-action]');if(!node||node.disabled||!ready)return;const {action,id,value}=node.dataset;
  if(action==='close')return closeModal();
  if(action==='library'){const link=document.createElement('a');link.href=sceneLink('deployments');if(!localPreview)link.target='_top';link.click();return;}
  if(action==='sound'){await audio.toggle();render();return;}
  if(!game)return;
  if(action==='start'||action==='brief')return openModal('brief');
  if(action==='deploy'){commit(engine.begin(game,state));closeModal();return;}
  if(action==='travel'){commit(engine.travel(game,state,id));$('#scene-title')?.setAttribute('tabindex','-1');$('#scene-title')?.focus();return;}
  if(action==='markers'){markers=!markers;render();return;}
  if(['baseline','evidence','notebook','choice','puzzle','recoveries','confirm-ending','checkpoints','restart'].includes(action))return openModal(action,id);
  if(action==='survey'){commit(engine.survey(game,state),'inspect');closeModal();notify(game.baseline.result);return;}
  if(action==='inspect'){commit(engine.inspect(game,state,id),'inspect');return openModal('evidence',id,true);}
  if(action==='enlarge-evidence'&&modal?.kind==='evidence'){modal.enlarged=!modal.enlarged;renderModal();$('#dialog-body').querySelector('[data-action="enlarge-evidence"]')?.focus({preventScroll:true});return;}
  if(action==='select-clue'){if(selectedClues.includes(id))selectedClues=selectedClues.filter(x=>x!==id);else selectedClues=[...selectedClues.slice(-1),id];return openModal('notebook',null,true);}
  if(action==='connect'){const result=engine.connect(game,state,selectedClues);commit(result.state,result.success?'deduction':null);notify(result.message);return openModal('notebook',null,true);}
  if(action==='hint'){hints[id]=(hints[id]||0)+1;return openModal(modal.kind,modal.id,true);}
  if(action==='choose'){const check=engine.choiceAvailability(game,state,id,value);if(!check.available)return notify(check.reason);checkpoint(`Before: ${byId(game.choices,id).title}`);commit(engine.choose(game,state,id,value),'choice');return openModal('choice',id,true);}
  if(action==='control'){const next=engine.setControl(game,state,id,value);commit(next);openModal('puzzle',null,true);$('#dialog-body').querySelector(`[data-id="${CSS.escape(id)}"][data-value="${CSS.escape(value)}"]`)?.focus({preventScroll:true});return;}
  if(action==='test'){const result=engine.testSetup(game,state);if(result.success&&!state.puzzle)checkpoint('Before the instrument test');commit(result.state,result.success?'deduction':null);notify(result.success?'Arrangement verified.':result.message);return openModal('puzzle',null,true);}
  if(action==='finish'){if(!engine.endingAvailability(game,state,id).available)return;checkpoint(`Before recovery: ${byId(game.endings,id).title}`);const next=engine.finish(game,state,id);if(!record().endings.includes(id))record().endings.push(id);commit(next,'ending');closeModal();window.scrollTo(0,0);return;}
  if(action==='rewind'){const saved=record().checkpoints[Number(id)];if(!saved)return;state=structuredClone(saved.state);record().checkpoints=record().checkpoints.slice(0,Number(id));selectedClues=[];save();render();closeModal();return;}
  if(action==='restart-confirm'){if(state.started)checkpoint('Previous run');state=engine.freshState(game);selectedClues=[];hints={};save();render();closeModal();return;}
  if(action==='download')download();
});
$('#dialog').addEventListener('cancel',event=>{event.preventDefault();closeModal();});
$('#dialog').addEventListener('click',event=>{if(event.target===$('#dialog')){const r=$('#dialog').getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)closeModal();}});
function suspend(){identityRevision++;ready=false;audio.pause();if($('#dialog').open)$('#dialog').close();$('#app').setAttribute('inert','');$('#app').setAttribute('aria-hidden','true');}
async function refresh(){const revision=++identityRevision;const next=await missionIdentity();if(revision!==identityRevision||document.hidden)return;if(next.allowed&&storageKey&&storageKey!==`bureau-deployments-v1:${next.storageKey}`){location.reload();return;}identity=next;$('#app').removeAttribute('inert');$('#app').removeAttribute('aria-hidden');if(!next.allowed){ready=false;audio.pause();$('#app').innerHTML=`<main id="main" class="gate"><img src="assets/brand/bo-lockup-stacked-no-division-paper.svg" alt="Bureau Obscura"><h1>${next.unavailable?'Account check unavailable':'Sign in to deploy'}</h1><p>${next.unavailable?'The account service did not respond. Try again in a moment.':'This assignment requires an authorized Bureau account.'}</p><a class="btn" href="${esc(accountLinks.signIn)}" ${topTarget}>Return to sign-in ↗</a></main>`;return;}
  if(!games.length){try{const loadedGames=await Promise.all(slugs.map(async slug=>{const r=await fetch(`games/${slug}.json`,{cache:'no-store'});if(!r.ok)throw new Error('Unavailable game');return r.json();}));if(revision!==identityRevision||document.hidden)return;games=loadedGames;storageKey=`bureau-deployments-v1:${identity.storageKey}`;loadBook();const slug=new URL(location.href).searchParams.get('game');game=games.find(g=>g.slug===slug)||null;state=game?(book[game.slug].state||engine.freshState(game)):null;}catch{$('#app').innerHTML='<main id="main" class="gate"><h1>The assignments could not load.</h1><p>Refresh this page to try again. Your saved progress is still in this browser.</p></main>';return;}}
  ready=true;render();if(modal)openModal(modal.kind,modal.id);}
document.addEventListener('visibilitychange',()=>document.hidden?suspend():refresh());
window.addEventListener('pagehide',suspend);
window.addEventListener('pageshow',event=>{if(event.persisted)refresh();});
window.addEventListener('focus',()=>{if(!document.hidden){suspend();refresh();}});
refresh();
